                    shadowed.add((node.name, arg.arg))
                if node.args.vararg is not None:
                    shadowed.add((node.name, node.args.vararg.arg))
                if node.args.kwarg is not None:
                    shadowed.add((node.name, node.args.kwarg.arg))
